using System.Text.Json;
using System.Text.Json.Nodes;
using System.Diagnostics;
using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
public static class ExperienceTestsI
{
 static int checks;static void Check(bool ok,string label){if(!ok)throw new Exception("STAGE I FAIL: "+label);Console.WriteLine("STAGE I PASS: "+label);checks++;}
 static DemoWorld Fresh(){var w=new DemoWorld();w.NewGame(1);w.WalletFunds=100000;w.Hangar["ore"]=100;w.EnsurePopulationC();return w;}
 static DemoWorld Reload(DemoWorld w){w.Save();var loaded=new DemoWorld();Check(loaded.Load(w.ActiveSavePath43),"save reload succeeds");return loaded;}
 public static void Run()
 {
  SkillCatalog.VerificationAllV=false;string? previous=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");string dir=Path.Combine(Path.GetTempPath(),"stage-i-"+Guid.NewGuid().ToString("N"));Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",dir);
  try{
   var w=Fresh();Check(w.ChooseCareerI("Prospector",true)==""&&w.NextGoalI?.Id=="mine","guided career and contextual first goal");w.ChooseCareerI("Freeform",false);Check(w.NextGoalI==null&&w.Experience.TutorialSkipped,"freeform skips guidance without changing world");w.ChooseCareerI("Explorer",true);
   w.Undock();w.EnterGrid("belt",false);var rock=w.Targets.First(t=>t.Kind==TargetKind.Asteroid);for(int n=0;n<5;n++)w.MiningHarvest(rock,15);Check(w.Experience.Achievements.Contains("mine"),"real mining earns extraction goal");Check(w.Experience.Progress["mine"]==50,"goal progress saturates and cannot duplicate achievement");
   w.DamageAuditF(w.Targets.First(t=>t.Kind==TargetKind.Raider));Check(w.Experience.Achievements.Contains("combat"),"real applied player damage earns combat goal");
   var probe=new ScanProbe{Id="test-probe",System=w.SystemId,Life=100,Connected=true,Enabled=true};w.ScanProbes.Add(probe);w.ProbeJob=new(){System=w.SystemId,Duration=1,Samples=[new(){Id=probe.Id}]};w.ProbeScanLeft=1;w.TickProbeScanning(1.1f);Check(w.Experience.Achievements.Contains("scan"),"completed probe analysis earns scanning goal");
   w.Screen=ViewMode.Station;w.Grid="station";w.Skills.Grant(IndustryCatalog37.BuildSkills(IndustryCatalog37.Recipes["miner"],false));w.SyncSkills();var bp=w.Industry.Blueprints.FirstOrDefault(b=>b.Item=="miner");if(bp==null){Check(w.BuyBlueprint("miner")=="","buy manufacturing blueprint");bp=w.Industry.Blueprints.Last();}foreach(var m in IndustryCatalog37.Recipes["miner"].Minerals)w.Hangar[m.Key]=10000;
   Check(w.InstallIndustry(bp.Id,IndustryActivity.Manufacturing)=="","install actual manufacturing job");var job=w.Industry.Jobs.Last();w.AdvanceHours((job.FinishUtc-w.Now).TotalHours+.001);Check(w.DeliverIndustry(job.Id)==""&&w.Experience.Achievements.Contains("industry"),"delivery earns industry goal");Check(w.DeliverIndustry(job.Id)!="","duplicate delivery cannot re-earn progress");Check(w.Experience.Achievements.Contains("graduate")&&w.SetTitleI("Independent Capsuleer")=="","complete actual career earns title");
   var scout=w.Population.Pilots.First(p=>p.Role=="Scout");Check(w.ContactPilotI(scout.Id)==""&&w.Experience.Messages.Last().Sender==scout.Id,"NPC contact creates linked mail");Check(w.PostMessageI("Local","Hello local pilots")==""&&w.Experience.Messages.Last().Recipients.All(id=>w.PopulationPilot(id)?.System==w.SystemId),"local recipients are actual colocated pilots");Check(w.PostMessageI("Corp","hello")!="","empty corporation channel rejects broadcast");Check(w.HirePopulationPilotC(scout.Id),"paid recruitment uses actual crew authority");Check(w.PostMessageI("Fleet","hold position")==""&&w.Experience.Messages.Last().Recipients.SequenceEqual(new[]{scout.Id}),"fleet channel only addresses active contracted pilots");
   Check(w.NegotiatePilotI(scout.Id)!="","negotiation requires earned shared service");scout.Experience=2;decimal wage=scout.Wage;Check(w.NegotiatePilotI(scout.Id)==""&&scout.Wage==wage-1,"earned negotiation changes actual wages");Check(w.NegotiatePilotI(scout.Id)!="","negotiation cooldown persists");
   w.Undock();w.EnterGrid("belt",false);scout.Grid=w.Grid;scout.System=w.SystemId;var target=w.Targets.First(t=>t.Kind==TargetKind.Asteroid);scout.Knowledge.Clear();Check(w.RequestIntelI(scout.Id)!="","unknown entities cannot be reported");scout.Knowledge[target.Id]=w.Now.AddSeconds(20);Check(w.RequestIntelI(scout.Id)=="","scout reports only an observed contact");var report=w.Experience.Intel.Single();Vector3 reported=report.Position;target.Position+=new Vector3(500,0,0);Check(report.Position==reported,"report is a snapshot, not a live tracking link");w.AdvanceHours(21d/3600);Check(!w.IntelFreshI(report),"intel ages and becomes stale on saved simulation clock");
   w.Screen=ViewMode.Station;w.Grid="station";Check(w.DesignCosmeticI("Cyan bands","Slate","Cyan","Bands")=="","valid hull-bound cosmetic draft");var design=w.Experience.Cosmetics.Last();Check(w.ApplyCosmeticI(design.Id)!="","unowned paint cannot apply");decimal funds=w.Balance,ore=w.Hangar["ore"];Check(w.SequenceCosmeticI(design.Id)==""&&w.Balance==funds-50&&w.Hangar["ore"]==ore-5,"sequencing consumes inputs once");Check(w.SequenceCosmeticI(design.Id)!="","no duplicate paid sequence");var sequence=w.Experience.Sequences.Last();Check(w.ClaimCosmeticI(sequence.Id)!="","unfinished sequence cannot be claimed");w.SimulationPaused=true;DateTime frozen=w.Now;w.Update(10);Check(w.Now==frozen&&sequence.State=="Active","pause freezes strategic and tactical time");w.SimulationPaused=false;w.AdvanceHours(1);Check(w.ClaimCosmeticI(sequence.Id)==""&&w.ApplyCosmeticI(design.Id)=="","ready local license can be collected and applied");Check(w.ClaimCosmeticI(sequence.Id)!="","claim is single settlement");
   var stats=w.Player.Attributes.Keys.ToDictionary(k=>k,k=>w.Player.Stat(k));Check(w.ApplyCosmeticI(design.Id)==""&&stats.All(k=>w.Player.Stat(k.Key)==k.Value),"cosmetic application does not affect performance");var trader=w.Population.Pilots.First(p=>p.Role=="Trader");decimal wallet=trader.Wallet;Check(w.BuyCosmeticI(trader.Id)==""&&trader.Wallet==wallet+100,"NPC listing credits real seller wallet");Check(w.BuyCosmeticI(trader.Id)!=""&&Math.Abs(w.PopulationMoneyErrorC)<.01m,"listing finite and NPC money ledger conserved");
   Check(w.RebindI("Inventory","Alt+Shift+I")==""&&w.BindingI("Inventory")=="Alt+Shift+I","primary binding persists in state");Check(w.RebindI("Market","G")!=""&&w.RebindI("Market","Delete")!="","duplicate and unsupported chords rejected");w.Experience.Settings.LargeText=true;w=Reload(w);Check(w.ActiveCosmeticI!=null&&w.BindingI("Inventory")=="Alt+Shift+I"&&w.Experience.Settings.LargeText,"owned applied paint and accessibility survive reload");Check(w.Experience.Achievements.Contains("graduate")&&w.Experience.Messages.Count>0&&w.Experience.Intel.Count>0,"goals, channels and intel survive reload");
   foreach(string kind in new[]{"fitting","skills","market","industry","assets","combat","cosmetics","completion"}){string export=w.ExportLocalI(kind);Check(File.Exists(export)&&JsonNode.Parse(File.ReadAllText(export))!=null,"valid local export / "+kind);}
   var fit=JsonNode.Parse(File.ReadAllText(Path.Combine(DemoWorld.ExportDirectoryI,"fitting.json")))!;Check(fit["Cpu"]!.GetValue<double>()==w.TotalFitCpu&&fit["Power"]!.GetValue<double>()==w.TotalFitPower,"exported fitting totals match authoritative display");
   var bad=new LocalPackI{Designs=[new(){Name="Valid",Hull=w.Player.CombatHull},new(){Name="Bad",Hull=w.Player.CombatHull,Primary="unknown"}]};string packPath=Path.Combine(dir,"pack.json");File.WriteAllText(packPath,JsonSerializer.Serialize(bad));int designs=w.Experience.Cosmetics.Count;Check(w.ImportLocalPackI(packPath)!=""&&w.Experience.Cosmetics.Count==designs,"pack import validates whole batch before mutation");bad.Designs.RemoveAt(1);bad.Designs[0].Owned=true;File.WriteAllText(packPath,JsonSerializer.Serialize(bad));Check(w.ImportLocalPackI(packPath)==""&&!w.Experience.Cosmetics.Last().Owned,"pack imports drafts, never ownership");File.WriteAllText(packPath,"{\"Schema\":1,\"InjectedCode\":\"x\"}");Check(w.ImportLocalPackI(packPath)!="","unknown mod fields rejected");w.Undock();w.EnterGrid("belt",false);Check(w.SubmitScienceI("Planet")!=""&&w.SubmitScienceI("AsteroidBelt")=="","optional science uses actual current geography");Check(w.SubmitScienceI("AsteroidBelt")!="","survey deduplication prevents repeated daily claims");
   w.Save();string save=File.ReadAllText(w.ActiveSavePath43);for(int schema=45;schema<=53;schema++){var data=JsonNode.Parse(save)!;data["SaveSchemaVersion"]=schema;data.AsObject().Remove("Experience");string path=Path.Combine(dir,"migration-"+schema+".json"),bytes=data.ToJsonString();File.WriteAllText(path,bytes);var old=new DemoWorld();Check(old.Load(path)&&File.ReadAllText(path+".pre-stage-i.bak")==bytes,"exact Stage I migration backup / "+schema);Check(old.Experience.Cosmetics.Count==0&&old.Player.Ore==w.Player.Ore,"migration preserves assets without inventing cosmetics / "+schema);}
   var invalid=JsonNode.Parse(save)!;invalid["Experience"]!["Settings"]!["RenderBudget"]=0;string badPath=Path.Combine(dir,"invalid.json");File.WriteAllText(badPath,invalid.ToJsonString());funds=w.Balance;Check(!w.Load(badPath)&&w.Balance==funds,"invalid experience rejected before changing active world");
   invalid=JsonNode.Parse(save)!;invalid["Experience"]!["Contacts"]!.AsArray().Add("unknown-pilot");File.WriteAllText(badPath,invalid.ToJsonString());Check(!w.Load(badPath)&&w.Balance==funds,"dangling NPC contact rejected before world mutation");
   Check(ReleaseCatalogI.Rows.Length==72&&ReleaseCatalogI.Rows.Select(r=>r.Id).Distinct().Count()==72,"full original requirement register published without duplicate IDs");Check(ReleaseCatalogI.Rows.All(r=>r.Status=="Partial"&&r.Remaining.Length>0),"completion register retains full-depth gaps");
   Console.WriteLine($"{checks} Stage I checks passed.");
  }finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",previous);if(Directory.Exists(dir))Directory.Delete(dir,true);}
 }
 public static void Soak()
 {
  string? previous=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");string dir=Path.Combine(Path.GetTempPath(),"stage-i-soak-"+Guid.NewGuid().ToString("N"));Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",dir);var timings=new List<object>();
  try{
   var w=Fresh();w.ChooseCareerI("Freeform",false);w.EnsureOrganisationsG();w.EnsureAdvancedH();DateTime start=w.Now;var timer=Stopwatch.StartNew();
   for(int month=0;month<36;month++){var batch=Stopwatch.StartNew();w.AdvanceHours(24*30);Check(Math.Abs(w.PopulationMoneyErrorC)<.01m,"NPC money conservation month "+(month+1));Check(w.Balance>=0&&w.Population.Businesses.All(b=>b.Wallet>=0&&b.Stock.Values.All(q=>q>=0))&&w.Population.Pilots.All(p=>p.Wallet>=0&&p.Cargo.Values.All(q=>q>=0)),"nonnegative economy month "+(month+1));if(month%6==5)w=Reload(w);timings.Add(new{Month=month+1,Milliseconds=batch.Elapsed.TotalMilliseconds,Memory=GC.GetTotalMemory(false),Pilots=w.Population.Pilots.Count,Orders=w.MarketOrders.Count,Shortages=w.Population.Businesses.Sum(b=>b.Shortages)});Console.WriteLine("SOAK month "+(month+1)+" / "+batch.Elapsed.TotalSeconds.ToString("0.00")+"s");}
   Check(w.Now-start==TimeSpan.FromDays(1080),"1080 simulated days retain one clock");Check(w.Population.Journal.Count<=800&&w.Experience.CombatArchive.Count<=2000,"journals remain bounded across campaign");w.Undock();w.EnterGrid("belt",false);Check(w.Targets.Any(t=>t.Kind==TargetKind.Asteroid)&&w.Player.Hull>0,"travel and playable ship remain after multi-year campaign");w.Screen=ViewMode.Station;w.Grid="station";w=Reload(w);Check(w.Load(w.ActiveSavePath43),"repeat reload remains valid");
   Console.WriteLine(JsonSerializer.Serialize(new{Profile="Legacy authored world / finite reserves / no synthetic restock",Days=1080,Seconds=timer.Elapsed.TotalSeconds,Environment=Environment.OSVersion.ToString(),Timings=timings},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("STAGE I SOAK PASSED");
  }finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",previous);if(Directory.Exists(dir))Directory.Delete(dir,true);}
 }
}
